@Composable internal fun DispatchVisitPanel(detail:VisitDetail,modifier:Modifier=Modifier){val context=LocalContext.current;val svc=remember{service(context)};val scope=rememberCoroutineScope();var data by remember(detail.id){mutableStateOf<Pair<DispatchVisitBindingEntity,List<DispatchItemBindingEntity>>?>(null)};var selfId by remember{mutableStateOf("")};var message by remember{mutableStateOf<String?>(null)};fun reload(){scope.launch{data=withContext(Dispatchers.IO){svc.dispatchDetail(detail.id)};selfId=withContext(Dispatchers.IO){svc.identity().technicianId}}};LaunchedEffect(detail.id){reload()};data?.let{(binding,items)->Card(modifier.fillMaxWidth().testTag("dispatched-visit")){Column(Modifier.padding(12.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){Text("Dispatched · generation ${binding.appliedGeneration}",style=MaterialTheme.typography.titleMedium);binding.managerReference?.let{Text("Job $it")};items.forEach{i->Text("${i.taskNameSnapshot}\n${if(i.assignmentMeaning=="EVERYONE")"Assigned to everyone" else "Assigned technicians preserved"} · ${i.localRole.replace('_',' ').lowercase()} · ${i.documentationDisposition.replace('_',' ').lowercase()}");if(detail.state=="WORKING"){if(i.documentationDisposition in setOf("PENDING","LEADER_OBSERVE"))Button({scope.launch{message=withContext(Dispatchers.IO){svc.documentLocally(detail.id,i.dispatchItemId)};reload()}},Modifier.fillMaxWidth()){Text("Document this item")};val candidates=((if(i.assignmentMeaning=="EVERYONE")svc.parseTech(binding.participantSnapshotJson)else svc.parseTech(i.assignedTechniciansJson))+svc.parseTech(binding.participantSnapshotJson).filter{it.technicianId in svc.parseIds(binding.leaderIdsJson)}).distinctBy{it.technicianId}.filter{it.technicianId!=selfId};val target=candidates.firstOrNull();if(i.localRole=="ASSIGNED"&&i.documentationDisposition!="DEFERRED"&&target!=null){OutlinedButton({scope.launch{runCatching{withContext(Dispatchers.IO){svc.handoff(detail.id,i.dispatchItemId,target)}}.onSuccess{message="Documentation handed off locally to ${target.name}; acceptance is not implied"}.onFailure{message=it.message};reload()}},Modifier.fillMaxWidth()){Text("Hand off documentation to ${target.name}")};TextButton({scope.launch{withContext(Dispatchers.IO){svc.handoff(detail.id,i.dispatchItemId,target,true)};message="Local draft discarded and documentation handed off";reload()}},Modifier.fillMaxWidth()){Text("Discard my local draft and hand off")}};if(i.documentationDisposition=="DEFERRED")OutlinedButton({scope.launch{withContext(Dispatchers.IO){svc.undoHandoff(detail.id,i.dispatchItemId)};reload()}},Modifier.fillMaxWidth()){Text("Document this item myself")}}};if(detail.state=="WORKING"&&items.filter{it.localRole=="ASSIGNED"}.all{it.documentationDisposition=="DEFERRED"}&&items.none{it.documentationDisposition=="DOCUMENT_LOCAL"})Button({scope.launch{withContext(Dispatchers.IO){svc.finishInvolvement(detail.id)};reload()}},Modifier.fillMaxWidth()){Text("Finish my involvement")};message?.let{Text(it,color=MaterialTheme.colorScheme.primary)}}}}}
